1: /**
2:  * 读取表格列配置（优先 vuex，刷新后从 localStorage 恢复）
3:  */
4: export function loadSavedTableConfig(store, tableId) {
5:   let config = store.getters['table/getTableConfig'](tableId)
6:   if (!config) {
7:     const raw = localStorage.getItem(`table_config_${tableId}`)
8:     if (raw) {
9:       try {
10:         config = JSON.parse(raw)
11:         store.commit('table/SET_TABLE_CONFIG', { tableId, config })
12:       } catch (e) {
13:         config = null
14:       }
15:     }
16:   }
17:   return config
18: }
19: 
